-- Series 20-10 (2-piece economical, quote-only Price NULL). Run from file (SSMS: File > Open > Execute).
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 20-10')
    INSERT INTO Categories (Name, CatalogUrl, DatasheetUrl, Description, BodyMaterial, SeatMaterial, Design, KeyFeatures)
    VALUES (N'Series 20-10', N'https://pblol2.blob.core.windows.net/mars-valves/catalogs/series-10-20.pdf', N'https://pblol2.blob.core.windows.net/mars-valves/catalogs/series-10-20.pdf',
        N'The Mars Series 20-10 is a 2-piece, full-port economical ball valve with threaded ends, rated to 1000 PSI. CF8M stainless steel body with PTFE/RTFE seats, in sizes 1/4" to 2", available with or without a locking device.',
        N'CF8M Stainless Steel', N'PTFE / RTFE', N'Two Piece, Full Port, Threaded Ends',
        N'2-piece full port design
Threaded ends (NPT, BSP, BSPT)
Rated to 1000 PSI
CF8M stainless steel body
PTFE / RTFE seats
Size 1/4" to 2"
Available with or without a locking device');

DECLARE @SeriesName nvarchar(100) = N'Series 20-10';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Size'),(N'End Connection'),(N'Operating Pressure'),(N'Lock')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Lock',2),(N'Operating Pressure',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

